import { useState } from 'react';

const INITIAL = [
  { id: 'a1', title: 'Arrival' },
  { id: 'p2', title: 'Past Lives' },
  { id: 'd3', title: 'Dune: Part Two' },
];

function MovieItem({ movie, onSelect, onRemove }) {
  return (
    <li>
      <button className="title" onClick={() => onSelect(movie.id)}>
        {movie.title}
      </button>
      <button className="remove" onClick={() => onRemove(movie.id)}>
        Remove
      </button>
    </li>
  );
}

export default function App() {
  const [movies, setMovies] = useState(INITIAL);
  const [selectedId, setSelectedId] = useState(null);
  const selected = movies.find((m) => m.id === selectedId);

  function handleRemove(id) {
    setMovies(movies.filter((m) => m.id !== id));
  }

  function handleKeyDown(e) {
    if (e.key === 'Escape') {
      setSelectedId(null);
    }
  }

  return (
    <main onKeyDown={handleKeyDown}>
      <p id="selected">Selected: {selected ? selected.title : 'none'}</p>
      <ul>
        {movies.map((movie) => (
          <MovieItem
            key={movie.id}
            movie={movie}
            onSelect={setSelectedId}
            onRemove={handleRemove}
          />
        ))}
      </ul>
    </main>
  );
}
